fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // Ensure the replacement array is non-empty (as specified in the problem)
    assert!(!values.is_empty(), "Replacement array must be non-empty");
    
    // Create result vector with the same length as input array
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through all elements
    for i in 0..a.len() {
        if mask[i] {
            // Use modulo to get the index in values array
            let value_index = i % values.len();
            result.push(values[value_index]);
        } else {
            result.push(a[i]);
        }
    }
    
    result
}